  "pop-doowop": { seq:["I–vi–IV–V loop","Verse/refrain"], dec:"Loop the 1950s I–vi–IV–V changes under close vocal harmony.", his:"1950s vocal-group R&B.", works:["The Penguins «Earth Angel»","The Chords «Sh-Boom»","«Stand By Me»"], rel:["pop-versechorus","jaz-rhythmchanges"] },
  "pop-riff": { seq:["Riff (intro)","Verse over riff","Chorus","Riff"], dec:"Generate the song from a repeated instrumental riff/hook.", his:"Blues-rock to hard rock and metal.", works:["Deep Purple «Smoke on the Water»","Black Sabbath «Iron Man»","Led Zeppelin «Whole Lotta Love»"], rel:["pop-breakdown","jaz-12bar","el-electro"] },
  "pop-powerballad": { seq:["Soft verse","Build","Huge chorus","Key-change finale"], dec:"Travel from intimate verse to soaring climax (often via key change).", his:"1980s–90s rock/pop ballad.", works:["Aerosmith «I Don't Want to Miss a Thing»","Bonnie Tyler «Total Eclipse of the Heart»","Whitney Houston «I Will Always Love You»"], rel:["pop-anthem","op-cavatina"] },
  "pop-breakdown": { seq:["Riff sections","Breakdown (half-time, heavy)","Out"], dec:"Drop to a heavy half-time section for maximum physical impact.", his:"Metalcore/hardcore device.", works:["Meshuggah «Bleed»","Lamb of God «Laid to Rest»","Killswitch Engage tracks"], rel:["pop-riff","el-brostep"] },
  "pop-tcepic": { seq:["Section A","Section B","… (no repeats)","Coda"], dec:"Through-compose a long multi-section track with little literal repetition.", his:"Progressive rock epics.", works:["Genesis «Supper's Ready»","Yes «Close to the Edge»","Pink Floyd «Dogs»"], rel:["pop-progsuite","rom-tonepoem","el-idm"] },
