  "pop-mathrock": { seq:["Cell A (odd meter)","Cell B","Recombination"], dec:"Build from interlocking riffs in shifting, odd time signatures.", his:"Math rock / post-hardcore.", works:["Don Caballero tracks","battles «Atlas»","tera Melos songs"], rel:["cla-scherzo","mod-totalserial","el-glitch"] },
  "pop-rnbvamp": { seq:["Groove/vamp","Verse","Hook","Vamp"], dec:"Ride a tight repeating groove; melody and ad-libs carry variation.", his:"Soul/R&B and neo-soul.", works:["D'Angelo «Untitled (How Does It Feel)»","Erykah Badu «On & On»","Marvin Gaye «What's Going On»"], rel:["pop-funk","jaz-vamp","el-boombap"] },
  "pop-funk": { seq:["One-chord vamp","«The One» downbeat","Breakdown"], dec:"Lock everything to a syncopated groove on a single chord — rhythm is the form.", his:"James Brown's funk revolution (mid-1960s).", works:["James Brown «Cold Sweat»","Sly & the Family Stone «Thank You»","Parliament «Flash Light»"], rel:["pop-rnbvamp","el-gfunk","folk-highlife"] },
