  "pop-synthpop": { seq:["Intro hook","Verse","Chorus","Synth break"], dec:"Build a pop song around synthesizer/drum-machine hooks.", his:"Early-1980s synth-pop.", works:["Depeche Mode «Just Can't Get Enough»","New Order «Blue Monday»","Eurythmics «Sweet Dreams»"], rel:["pop-versechorus","el-electro","pop-hyperpop"] },
